// Rebuilds fixtures.ts (the .jsonl files as strings: `claude plugin test` can import only code files) from the .jsonl fixtures here.
// The JSONL inputs contain synthetic Acme Notes events.
// Run: node tests/fixtures/codex/sync-fixtures.mjs
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('.', import.meta.url))
const FILES = { ROLLOUT_FINISHED: 'rollout-finished.jsonl', ROLLOUT_UNFINISHED: 'rollout-unfinished.jsonl', EVENTS: 'events.jsonl', DELEGATIONS: 'delegations.jsonl', ROLLOUT_SMOKE: 'rollout-smoke.jsonl', DELEGATIONS_SMOKE: 'delegations-smoke.jsonl' }
const body = Object.entries(FILES).map(([name, file]) => `export const ${name} = ${JSON.stringify(readFileSync(dir + file, 'utf8'))}\n`)
writeFileSync(dir + 'fixtures.ts', `// GENERATED by sync-fixtures.mjs from the .jsonl files beside it. Do not edit by hand.\n${body.join('')}`)
